<script setup lang="ts">import {computed} from 'vue';import {fixed} from '../utils/format';const props=defineProps<{result:any}>();const conv=computed(()=>props.result.conversion);const ratio=computed(()=>{const v=props.result.variance_ratio_analysis??props.result.deming?.lambda;return v===undefined||v===null||!Number.isFinite(Number(v))?null:Number(v)});const inputRatio=computed(()=>props.result.variance_ratio_input);const adjusted=computed(()=>inputRatio.value!==undefined&&ratio.value!==null&&Math.abs(Number(inputRatio.value)-ratio.value)>1e-15)</script><template><article class="conversion-basis"><p class="eyebrow">UNIT BASIS / 换算依据</p><div class="conversion-grid"><div><small>X侧原单位</small><strong>{{result.x_unit||result.unit}}</strong></div><div><small>Y侧原单位</small><strong>{{result.y_unit||result.unit}}</strong></div><div><small>分析单位</small><strong>{{result.unit}}</strong></div><div><small>误差方差比 λ</small><strong>{{ratio===null?'未记录':ratio}}</strong><span v-if="adjusted">原单位输入 {{inputRatio}} → 换算后</span><span v-else-if="ratio!==null">与原单位输入一致</span><span v-else>旧快照未单独记录</span></div></div><p v-if="conv&&conv.basis" class="conversion-note">{{conv.basis}}</p><p v-else class="conversion-note">该结果两侧同单位；归档快照未记录换算依据，数值按当时口径保持原值。</p><p v-if="conv&&conv.variance_ratio_note" class="conversion-note">{{conv.variance_ratio_note}}</p><p class="conversion-note">讨论容差 ±{{fixed(result.tolerance,3)}} 按分析单位 {{result.tolerance_unit||result.unit}} 解释；原始读数 {{result.x_unit||result.unit}} / {{result.y_unit||result.unit}} 均原样保留。</p></article></template>
